args.content:
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 5.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Enable required APIs
resource "google_project_service" "run_api" {
  service            = "run.googleapis.com"
  disable_on_destroy = false
}

resource "google_project_service" "artifactregistry_api" {
  service            = "artifactregistry.googleapis.com"
  disable_on_destroy = false
}

# Create Artifact Registry Repository
resource "google_artifact_registry_repository" "repo" {
  depends_on    = [google_project_service.artifactregistry_api]
  location      = var.region
  repository_id = "hello-world-repo"
  description   = "Docker repository for the Hello World web service"
  format        = "DOCKER"

  cleanup_policies {
    id     = "keep-minimum-versions"
    action = "KEEP"
    most_recent_versions {
      keep_count = 3
    }
  }
}

# Create dedicated Service Account for Cloud Run
resource "google_service_account" "run_sa" {
  account_id   = "hello-world-run-sa"
  display_name = "Cloud Run Runtime Service Account"
}

# Create Cloud Run Service (v2)
resource "google_cloud_run_v2_service" "web_service" {
  name     = var.service_name
  location = var.region
  ingress  = "INGRESS_TRAFFIC_ALL"

  template {
    service_account = google_service_account.run_sa.email

    containers {
      image = var.image_uri

      ports {
        container_port = 8080
      }

      resources {
        limits = {
          cpu    = "1"
          memory = "512Mi"
        }
      }
    }
  }

  depends_on = [
    google_project_service.run_api,
    google_service_account.run_sa
  ]
}

# Allow unauthenticated public access
resource "google_cloud_run_v2_service_iam_member" "public_access" {
  name     = google_cloud_run_v2_service.web_service.name
  location = google_cloud_run_v2_service.web_service.location
  role     = "roles/run.invoker"
  member   = "allUsers"
}

